(()=>{const r=matchMedia('(prefers-reduced-motion:reduce)').matches,s=document.createElement('style');s.textContent=`@keyframes ip{50%{text-shadow:0 0 18px #fff,0 0 46px #00d9ff,0 0 64px #ff8a00;transform:scale(1.03)}}@keyframes out{to{opacity:0;visibility:hidden}}@keyframes pop{to{opacity:0;transform:translate(-50%,-50%) scale(1.8) rotate(40deg)}}.site-intro{position:fixed;inset:0;z-index:9999;display:grid;place-items:center;text-align:center;padding:24px;background:radial-gradient(circle,#1594ff,#0060c7 58%,#003d82);transition:.5s}.site-intro.hide{animation:out .55s forwards}.site-intro b{font-size:clamp(34px,7vw,82px);line-height:1;color:#fff;text-transform:uppercase;letter-spacing:-2px;animation:ip .7s ease-in-out infinite alternate}.site-intro b span{color:#ff9d00}.trail{position:fixed;z-index:9998;pointer-events:none;left:0;top:0;width:20px;height:20px;display:grid;place-items:center;font-size:16px;filter:drop-shadow(0 0 5px #fff) drop-shadow(0 0 9px #00d9ff) drop-shadow(0 0 10px #ff8a00);transform:translate(-50%,-50%);animation:pop .65s forwards}@media(prefers-reduced-motion:reduce){.site-intro b,.trail{animation:none}.trail{display:none}}`;document.head.appendChild(s);const i=document.createElement('div');i.className='site-intro';i.innerHTML='<b>THE DEPTHS OF <span>IMMUNOTHERAPY</span></b>';document.body.prepend(i);setTimeout(()=>i.classList.add('hide'),r?250:1350);setTimeout(()=>i.remove(),r?850:2000);let last=0,n=0;function p(x,y){if(r)return;const e=document.createElement('i');e.className='trail';e.textContent=n++%3===0?'🧬':'✦';e.style.left=x+'px';e.style.top=y+'px';e.style.color=n%2?'#00d9ff':'#ff8a00';document.body.appendChild(e);setTimeout(()=>e.remove(),700)}addEventListener('pointermove',e=>{if(e.pointerType==='mouse'&&performance.now()-last>55){last=performance.now();p(e.clientX,e.clientY)}});addEventListener('pointerdown',e=>{for(let j=0;j<3;j++)setTimeout(()=>p(e.clientX+(Math.random()-.5)*30,e.clientY+(Math.random()-.5)*30),j*55)})})();